// Class 8 Science practice bank, part 3: Investigative World of Science to Particulate Nature of Matter. Extra questions for year-long practice.
(function () {
  const AR_OPTS = ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."];
  let n = 3 - 1;
  // M(level, question, right answer, three wrong answers, explanation, objective?): the right answer is stored at a varying position.
  function M(level, q, right, wrong, explain, obj) {
    const at = (n++) % 4;
    const options = wrong.slice();
    options.splice(at, 0, right);
    const o = { q, options, answer: at, explain, level };
    if (obj) o.obj = obj;
    return o;
  }
  // AR(level, assertion, reason, answer index, explanation, objective?): assertion–reason with fixed options.
  function AR(level, a, r, answer, explain, obj) {
    const o = { q: "Assertion (A): " + a + "\nReason (R): " + r, options: AR_OPTS, answer, explain, level, keepOrder: true };
    if (obj) o.obj = obj;
    return o;
  }
  function W(marks, q, a, type, obj) {
    const o = { q, a, marks };
    if (type) o.type = type;
    if (obj) o.obj = obj;
    return o;
  }
  StudyData.addPractice(8, "science", {
  "investigative-world-of-science": {
    mcq: [
      M(1, "In the sequence observe → question → hypothesis → experiment → record data → analyse, the step that comes last is the", "conclusion", ["question", "observation", "hypothesis"], "After the data are analysed, the scientist writes a conclusion that follows from the evidence."),
      M(1, "Which question can be answered by doing an experiment?", "Does a bigger magnet pick up more iron pins?", ["Which colour is the nicest?", "Is a cricket bat luckier than a hockey stick?", "Was yesterday a good day?"], "Only a question that can be answered by measuring something can be tested. The others are matters of opinion or belief."),
      M(1, "The average of the readings 18, 22 and 20 is", "20", ["60", "22", "19"], "Sum = 18 + 22 + 20 = 60. Average = 60 ÷ 3 = 20. The number 60 is only the sum."),
      M(1, "To find out whether salt changes the time ice takes to melt, a cup of ice with no salt is kept. This cup is the", "control", ["dependent variable", "hypothesis", "conclusion"], "The control is the set-up in which the variable is not changed, so that it can be compared."),
      M(1, "A scientist who changes her explanation when new evidence appears is showing", "a scientific attitude", ["poor memory", "a lack of self-confidence", "careless work"], "Openness to changing ideas when evidence changes is part of a scientific attitude."),
      M(1, "Before starting an experiment that uses fire or chemicals, a student should first", "follow the teacher's instructions and safety rules", ["start quickly to save time", "taste the chemical to identify it", "work without telling anyone"], "Fire, glass and chemicals can be dangerous, so safety rules and the teacher's instructions come first."),
      M(1, "Which instrument is best for measuring the time a rolling ball takes to travel along a table?", "A stopwatch", ["A thermometer", "A measuring tape", "A beam balance"], "Time is measured with a stopwatch. Using the right instrument and unit is part of recording data."),
      M(1, "Microscopes helped scientists to discover cells, and the study of cells led to new medical tools. This shows that", "science and technology improve each other", ["technology is of no use to science or medicine", "science does not need instruments", "scientific facts never change"], "New instruments reveal new facts, and new facts lead to new technology."),
      M(2, "Ravi measures a bean plant every 5 days: 2 cm on day 0, 4 cm on day 5, 6 cm on day 10 and 8 cm on day 15. What pattern do the readings show?", "The plant grows 2 cm in every 5 days", ["The plant grows 2 cm every day", "The plant grows by a different amount each time", "The plant stops growing after day 10"], "Each reading is 2 cm more than the one before it, and the readings are 5 days apart."),
      M(2, "Four students time a toy car: 12.5 s, 12.0 s, 12.5 s and 13.0 s. The value that should be reported is", "12.5 s", ["50 s", "12.0 s", "13.0 s"], "Sum = 12.5 + 12.0 + 12.5 + 13.0 = 50 s. Average = 50 ÷ 4 = 12.5 s."),
      M(2, "Two ice cubes of the same size are kept, one in sunlight and one in shade, to see whether sunlight affects melting. The independent variable is", "the place where the cube is kept (sunlight or shade)", ["the time taken to melt", "the size of the cube", "the number of cubes"], "The independent variable is the factor that is deliberately changed. The time taken to melt is measured, so it is the dependent variable."),
      M(2, "Asha puts different numbers of coins on identical paper boats and notes how deep each boat sinks. The dependent variable is", "the depth to which the boat sinks", ["the number of coins", "the kind of paper used for all the boats", "the water in the tub"], "The depth is what is measured as a result of the change. The number of coins is the factor she changes."),
      M(2, "After an experiment, the results do not support the hypothesis. What does this tell the scientist?", "The hypothesis is not supported, so a new one can be made and tested", ["The experiment was a waste of time", "The readings must be changed to fit", "The question can never be studied"], "A rejected hypothesis is still a useful result. It leads to a better explanation that can be tested."),
      M(2, "Meera washes one cloth with soap A in hot water and another with soap B in cold water to compare the soaps. What is wrong with her test?", "Two factors (soap and water temperature) are changed together", ["She used two cloths", "She used soap", "She did not wash either cloth for long enough in both of the cases"], "In a fair test only one factor is changed. Here the soap and the temperature both differ, so the cause of any difference cannot be known."),
      M(2, "Which of these is an observation and not an explanation?", "The candle flame went out when a glass was placed over it", ["Flames need oxygen to burn", "The candle was too small", "Candles should be kept under glass jars"], "An observation is what is seen or measured. The other statements explain or advise."),
      M(2, "Which statement is a hypothesis that can be tested?", "If a plant gets more light, it will grow taller", ["The plant grew 3 cm last week", "How tall will the plant grow?", "Always wear gloves and a mask while handling soil"], "A hypothesis is a testable explanation or prediction. The others are a result, a question and a rule."),
      M(2, "A student times only one swing of a pendulum and reports that time. A better method is to", "take several readings and use their average", ["use only the smallest one of all the readings", "guess the time after one try", "ask a friend what the answer should be"], "Repeating the measurement and averaging reduces the effect of chance errors."),
      M(2, "A tea-stall owner times a sugar cube in tea: 90 s at 30 °C, 50 s at 50 °C and 30 s at 70 °C. What conclusion do the readings support?", "Sugar dissolves faster as the tea gets hotter", ["Sugar dissolves faster as the tea becomes cooler", "Temperature has no effect on dissolving", "Sugar never dissolves in tea"], "The time taken falls as the temperature rises, so dissolving is quicker in hotter tea."),
      M(2, "A graph of a plant's height against the number of days shows a line rising steadily. What does this tell us?", "The height increases as the days pass", ["The height decreases as the days pass", "The height stays the same", "The plant has stopped growing"], "A rising line means the quantity on the vertical axis grows as the quantity on the horizontal axis grows."),
      M(2, "A girl repeats an experiment five times and the readings differ slightly each time. The most likely reason is", "chance errors that affect every measurement", ["the experiment can never work", "the readings must always be exactly identical", "the hypothesis has changed"], "Small random differences are common in measurement, which is why the average of several readings is used."),
      M(2, "A dependent variable in a test of how the slope of a ramp affects the distance a toy car rolls is", "the distance the car rolls", ["the angle of slope of the ramp", "the toy car used", "the floor surface"], "The distance is measured as the result. The slope is what is changed, and the car and floor are kept the same."),
      M(3, "To test whether a fertiliser makes tomato plants grow taller, Gurpreet puts the fertiliser on 10 plants. Which addition makes the test fair?", "Ten similar plants with no fertiliser, kept in the same soil, water and light", ["Ten plants of another kind kept in the shade with no fertiliser", "Ten plants given a different fertiliser", "Measuring the fertilised plants twice"], "A fair test needs a control: similar plants treated in the same way except for the fertiliser."),
      M(3, "In an investigation on whether the mass of the bob changes the time of a pendulum, which should be kept the same?", "The length of the string and the angle of release", ["The mass of the bob", "The time of one swing", "The number of readings"], "Only the mass is changed, so the other factors that might affect the swing must be kept fixed."),
      M(3, "Four timings of a ball's fall are 5.1 s, 5.0 s, 5.2 s and 9.9 s. What should an honest scientist do about the 9.9 s?", "Note it, look for a mistake and repeat the measurement", ["Delete it without telling anyone", "Change it to 5.1 s", "Use only the 9.9 s"], "Odd readings must not be hidden or altered. They are checked and the measurement is repeated."),
      M(3, "Which plan is the best way to find out whether the colour of a cloth affects how warm it gets in sunlight?", "Cloths of the same size and different colours kept in the same sunny place, with the temperature measured after the same time", ["A white cloth in sunlight and a black cloth in shade", "Large and small cloths of the same colour kept in different places", "One cloth of each colour, measured at different times of the day"], "Only the colour changes. Size, place and time are kept the same so that the colour is the only reason for any difference."),
      M(3, "Over the years, a farmer notes that in each of three seasons the crop did well after he sowed on a particular day. He says that the day causes a good crop. Which statement is the best reply?", "Three cases are not enough; a fair test that compares other sowing days with all else kept the same is needed", ["He is right, because it happened every time", "He is wrong, because the day of sowing can never matter", "Only the opinion of elders matters"], "A conclusion must come from a fair test with a comparison, not from a few cases where something else may have helped."),
    ],
    written: [
      W(1, "Name the independent and the dependent variable in this investigation: how the length of a rubber band affects how far it stretches when a weight is hung from it.", "Independent variable: the weight hung (or the length of the band, whichever is changed). Dependent variable: how far the band stretches, which is measured.", "short"),
      W(2, "Why should a scientist write down every reading honestly, even a reading that looks odd?", "The conclusion must be based on real evidence. Hiding or changing a reading gives a false conclusion. An odd reading is checked and the measurement repeated instead.", "short"),
      W(2, "Arrange these steps in the right order: analyse the data, make a hypothesis, observe, do the experiment, write the conclusion, ask a question, record the data.", "Observe → ask a question → make a hypothesis → do the experiment → record the data → analyse the data → write the conclusion.", "short"),
      W(2, "What is a control? Explain why it is useful with an example.", "A control is a set-up in which the variable is not changed. It gives a fair comparison. Example: to test whether sunlight helps a plant, keep one plant in sunlight and a similar plant in the dark; the plant in the dark is the control. Any difference in growth can then be put down to the light.", "short"),
      W(2, "A student finds the readings 3.2 s, 3.0 s and 3.1 s for a trolley to roll down a slope. Calculate the value she should report.", "Sum = 3.2 + 3.0 + 3.1 = 9.3 s. Average = 9.3 ÷ 3 = 3.1 s.", "short"),
      W(3, "Write three qualities of a scientific attitude and explain how one of them helps in an investigation.", "Curiosity, honesty, patience and openness to change ideas are some qualities. Honesty: the scientist records the readings as they are, so the conclusion is based on true evidence.", "short"),
      W(3, "Explain why a shopkeeper's claim that 'children who take my tonic become taller' cannot be accepted from the stories of a few children. Suggest how to test it.", "Children grow taller with age anyway, and the few cases are not compared with anyone. A fair test would take two similar groups of children, give the tonic to one group only, keep diet and age the same, measure the heights of both groups at the start and after some months, and compare the changes.", "short"),
      W(4, "Plan an experiment to find whether the amount of water affects the growth of green gram (moong) seedlings. State the variable, what is measured, what is kept the same and how you will make the results reliable.", "Independent variable: the amount of water given each day (for example 10 mL, 20 mL and 40 mL).\nMeasured: the height of the seedlings after a fixed number of days.\nKept the same: seed type and number of seeds, soil, pot size, light and temperature.\nReliability: use several pots for each amount, measure the heights, take the average for each amount and compare the averages. Keep one pot with no water as a control.", "long"),
      W(4, "Case study: Kabir tests three kinds of paper to find which one soaks up the most water. He puts equal strips of paper A, B and C into the same amount of water for one minute and measures how high the water rises: A 2 cm, B 5 cm, C 3 cm. He repeats it and gets 2 cm, 6 cm and 3 cm.\n(i) What is the independent variable?\n(ii) Find the average rise for paper B.\n(iii) Which paper soaks up the most water, and what two things were kept the same?", "(i) The kind of paper (A, B or C).\n(ii) Average for B = (5 + 6) ÷ 2 = 5.5 cm.\n(iii) Paper B soaks up the most water. The size of the strips, the amount of water and the time were kept the same (any two).", "case"),
      W(5, "A group of students suspects that mothballs (naphthalene) vanish faster in a warm room than in a cool one. Write a hypothesis, describe a fair test, say what readings to record and how the conclusion should be written.", "Hypothesis: mothballs of the same size vanish faster in a warm room than in a cool room.\nFair test: take two mothballs of the same size and mass, keep one in a warm place and the other in a cool place, in similar containers, with the same air flow.\nReadings: measure the mass of each ball every day with a balance, in a table, and repeat with more mothballs to take averages.\nConclusion: compare the loss of mass in the two places and state what the evidence shows, for example 'the ball in the warm room lost more mass, so the hypothesis is supported'. If the readings do not show this, the hypothesis is rejected and a new one is made.", "long"),
    ],
  },
    "invisible-living-world": {
    mcq: [
      M(1, "Who used simple lenses to observe tiny living organisms in water?", "Anton van Leeuwenhoek", ["Alexander Graham Bell", "Edward Jenner", "Hans Oersted"], "Leeuwenhoek saw tiny living organisms in water with simple lenses. Hooke named the cell after looking at cork."),
      M(1, "The jelly-like fluid that fills a cell is the", "cytoplasm", ["nucleus", "cell wall", "vacuole"], "The cytoplasm is the jelly-like fluid in which the other parts of the cell lie."),
      M(1, "Which structure is present in plant cells but not in animal cells?", "Cell wall", ["Nucleus", "Cytoplasm", "Cell membrane"], "Plant cells have a cell wall as well as a membrane. Animal cells have only the membrane."),
      M(1, "Chloroplasts in green plant cells help the plant to", "make food by photosynthesis", ["store water only", "control the cell's activities", "decide what enters the cell"], "Chloroplasts contain the green pigment and carry out photosynthesis."),
      M(1, "Which of these is a multicellular organism?", "A banyan tree", ["Amoeba", "Paramecium", "A single red blood cell"], "A tree has very many cells. Amoeba and Paramecium are single-celled."),
      M(1, "Cholera is caused by a", "bacterium", ["virus", "fungus", "protozoan"], "Cholera is a bacterial disease. Influenza is viral and malaria is caused by a protozoan."),
      M(1, "Round red blood cells and long nerve cells show that", "cells differ in shape and size according to their job", ["all cells are identical", "only animal cells have a shape", "cells change shape when we sleep"], "The shape of a cell suits its work, so cells in the body are not all alike."),
      M(1, "Microorganisms are living organisms that", "cannot be seen without a microscope", ["are always harmful to every living thing", "live only in water", "are all bigger than insects"], "Microbes are too small to be seen with the naked eye. Many are useful and they live almost everywhere."),
      M(2, "A microscope has a 10× eyepiece and a 15× objective. The total magnification is", "150×", ["25×", "1500×", "15×"], "Total magnification = 10 × 15 = 150×."),
      M(2, "A student wants a total magnification of 400× with a 40× objective. The eyepiece she needs is", "10×", ["16×", "100×", "360×"], "Eyepiece = 400 ÷ 40 = 10×."),
      M(2, "A student keeps a 10× eyepiece but changes the objective from 10× to 40×. The total magnification becomes", "4 times as large", ["30 times as large", "40 times as large", "the same"], "100× becomes 400×, which is 4 times as large, because the objective is 4 times as strong."),
      M(2, "Hooke used the word 'cell' because the thin slices of cork he examined", "showed small box-like compartments", ["showed tiny moving organisms in the sap", "had a nucleus in every part", "looked like blood"], "The compartments reminded him of small rooms, so he called them cells."),
      M(2, "A leaf cell shows a green body and a firm outer wall. A cheek cell of a human shows neither. Which pair of structures was seen only in the leaf cell?", "Cell wall and chloroplasts", ["Nucleus and cytoplasm", "Nucleus and cell membrane", "Cytoplasm and chloroplasts"], "Cell walls and chloroplasts are found in plant cells but not in animal cells. Both cells have a nucleus, cytoplasm and membrane."),
      M(2, "Which statement about Paramecium is correct?", "It is a single cell that carries out all its life activities", ["It is a tissue made of many cells", "It is a virus that needs a host", "It has organs and organ systems"], "A unicellular organism does every job within its one cell."),
      M(2, "Which of these is an organ?", "The heart", ["A nerve cell", "Muscle tissue", "The circulatory system"], "An organ is made of tissues working together. A nerve cell is a cell, and the circulatory system is an organ system."),
      M(2, "Which of these is not made of cells?", "A virus", ["Yeast", "A bacterium", "Amoeba"], "Viruses are not cells. They can multiply only inside a living host cell."),
      M(2, "Which pair correctly names the microbe used?", "Curd — bacteria; bread dough — yeast", ["Curd — yeast; bread dough — bacteria", "Curd — virus; bread dough — protozoa", "Curd — protozoa; bread dough — virus"], "Bacteria turn milk into curd and yeast makes dough rise."),
      M(2, "Which disease is caused by a protozoan?", "Malaria", ["Cholera", "Influenza", "Typhoid"], "Malaria is caused by a protozoan. Cholera and typhoid are bacterial, and influenza is viral."),
      M(2, "Malaria passes from one person to another through the bite of", "an Anopheles mosquito", ["a housefly sitting on food", "a bat", "an Amoeba"], "The mosquito carries the protozoan from an infected person to a healthy one."),
      M(2, "Which sequence goes from the smallest to the largest unit of organisation?", "Nerve cell, nervous tissue, brain, nervous system", ["Brain, nervous system, nerve cell, nervous tissue", "Nervous system, brain, nervous tissue, nerve cell", "Nervous tissue, nerve cell, nervous system, brain"], "Cells make tissues, tissues make an organ (brain), and organs working together make an organ system."),
      M(2, "Which job of microorganisms helps the environment?", "They decompose dead plants, animals and waste", ["They make rain fall", "They make their own food from sunlight in the soil", "They cause every disease"], "Decomposer microbes break down waste, so the dead matter does not pile up."),
      M(3, "A student has eyepieces of 5× and 10×, and objectives of 4×, 10× and 40×. She needs a total magnification of exactly 200×. Which combination should she use?", "5× eyepiece with 40× objective", ["10× eyepiece with 10× objective", "10× eyepiece with 40× objective", "5× eyepiece with 10× objective"], "5 × 40 = 200×. The others give 100×, 400× and 50×."),
      M(3, "A microscope gives 600× with a 15× eyepiece. If the objective is changed to one that is half as strong, the new magnification is", "300×", ["600×", "150×", "1200×"], "Objective = 600 ÷ 15 = 40×. Half of that is 20×. New magnification = 15 × 20 = 300×."),
      AR(3, "Green plant cells can make their own food.", "Plant cells have a cell wall.", 1, "A is true because chloroplasts carry out photosynthesis. R is also true, but the cell wall does not make food, so it does not explain A."),
      M(3, "Which statement about unicellular and multicellular organisms is correct?", "In a unicellular organism one cell does all the jobs, but in a multicellular organism the cells share the jobs", ["Unicellular organisms have tissues but multicellular ones do not", "Multicellular organisms are made of one very large cell", "Unicellular organisms are all disease-causing"], "Cells of a multicellular body are specialised for different jobs. A single-celled organism performs them all within itself."),
    ],
    written: [
      W(1, "Write the formula for the total magnification of a compound microscope.", "Total magnification = magnification of the eyepiece × magnification of the objective.", "short"),
      W(1, "State the function of the cell membrane.", "The cell membrane controls what enters the cell and what leaves it.", "short"),
      W(2, "Name two parts found only in plant cells and state the function of each.", "Cell wall: gives the plant cell a firm shape and protects it. Chloroplasts: contain the green pigment and make food by photosynthesis. (A large vacuole is also found in plant cells.)", "short"),
      W(2, "Give two examples of unicellular organisms and two of multicellular organisms.", "Unicellular: Amoeba, Paramecium. Multicellular: human beings, trees (any other suitable examples).", "short"),
      W(2, "A microscope has a 5× eyepiece. What objective is needed to give a total magnification of 250×?", "Total magnification = eyepiece × objective, so objective = 250 ÷ 5 = 50×.", "short"),
      W(3, "Using the human body as an example, explain how cells, tissues, organs and organ systems are related.", "Similar cells working together form a tissue, for example muscle cells form muscle tissue. Different tissues make an organ, for example the stomach. Organs that work together make an organ system, for example the digestive system. The organ systems together make up the organism.", "short"),
      W(3, "Compare red blood cells and nerve cells in shape, and explain why cells differ in shape.", "Red blood cells are round and nerve cells are long. The shape of a cell suits the work it does, so cells in different parts of the body differ in shape and size.", "short"),
      W(4, "Case study: Gurleen's mother sets a spoonful of curd in warm milk at night. By morning the milk has turned into curd. Gurleen then sees her baker uncle add a little yeast to flour and water, and the dough rises.\n(i) Which microorganism turns milk into curd?\n(ii) Name the microorganism that makes the dough rise.\n(iii) Give one harmful role of a microorganism and name the disease.", "(i) Bacteria.\n(ii) Yeast, which is a fungus.\n(iii) Some microorganisms cause disease, for example the protozoan that causes malaria, a bacterium causing cholera or a virus causing influenza (any one).", "case"),
      W(4, "Draw up a table of differences between a plant cell and an animal cell using four points, then give one similarity.", "Plant cell: has a cell wall; has large vacuole; has chloroplasts in green parts; shape is usually fixed. Animal cell: no cell wall; vacuoles small or absent; no chloroplasts; shape is usually changeable. Similarity: both have a cell membrane, cytoplasm and a nucleus.", "long"),
      W(5, "Describe how a compound microscope gives a large image. Find the total magnification when the eyepiece is 10× and the objective is 40×, and say what happens to it if the objective is replaced by a 10× lens.", "A compound microscope has two lenses. The objective, near the object, forms an enlarged image, which the eyepiece enlarges again. The total magnification is the product of the two.\nTotal = 10 × 40 = 400×.\nWith a 10× objective: 10 × 10 = 100×. The magnification becomes one quarter of what it was, so objects look smaller.", "long"),
    ],
  },
    "health-the-ultimate-treasure": {
    mcq: [
      M(1, "Which of these is a part of social well-being?", "Having good relationships with family and friends", ["Eating three sweets a day", "Staying away from every person", "Owning a large house"], "Health includes social well-being, which comes from good relationships and a caring community."),
      M(1, "Diabetes is called a non-infectious disease because it", "does not spread from one person to another through germs", ["is not a disease at all", "spreads through the air", "is caused only by mosquitoes"], "Non-infectious diseases such as diabetes do not pass to others by germs."),
      M(1, "Which of these diseases is spread by a mosquito vector?", "Dengue", ["Cholera", "Typhoid", "The common cold"], "Dengue is carried by mosquitoes. Cholera and typhoid spread by water and food, and the cold by air."),
      M(1, "Typhoid mainly spreads through", "contaminated water and food", ["the bites of mosquitoes at night", "sunlight", "touching a mirror"], "Typhoid germs pass on in unsafe water and food."),
      M(1, "Which habit helps to look after mental health?", "Talking to a family member or friend when you are worried", ["Avoiding everyone", "Using tobacco to relax", "Staying awake all night"], "Talking, play, hobbies, yoga and sleep support mental well-being."),
      M(1, "Which of these should be avoided for good health?", "Tobacco", ["Adequate sleep", "Clean drinking water", "Outdoor play"], "Tobacco, alcohol and other harmful substances damage health."),
      M(1, "Polio has been nearly eliminated by", "vaccination", ["antibiotics", "mosquito nets", "boiling milk"], "Large vaccination programmes have almost wiped out polio."),
      M(1, "Washing hands before meals helps because it", "stops germs from getting into the body with food", ["makes the food tastier", "kills the germs inside the stomach", "gives vitamins"], "Hand washing removes germs that may otherwise be swallowed."),
      M(2, "A doctor does not give antibiotics to a child with influenza. The reason is that", "influenza is caused by a virus, and antibiotics act against bacteria", ["antibiotics make influenza worse", "influenza is not a disease", "antibiotics act only on fungi"], "Antibiotics work against bacteria and not viruses, so they will not help in influenza."),
      M(2, "A child receives a vaccine. Which statement is true?", "The child is protected before ever meeting the germ", ["The child is treated after becoming ill", "The child gets the full disease", "The germs in all the water the child drinks are killed"], "A vaccine trains the body's defences to recognise the germ without the full disease."),
      M(2, "Which action would raise the risk of malaria and dengue?", "Storing water in open, uncovered containers", ["Emptying old tyres of water", "Covering water tanks", "Removing all the stagnant water near homes and streets"], "Mosquitoes breed in standing water, so uncovered water supports them."),
      M(2, "A town records dengue cases each week: week 1, 5; week 2, 12; week 3, 30 after heavy rain; week 4, 10 after a drive to remove stagnant water. What does the table suggest?", "Standing water helped mosquitoes to breed, and removing it reduced the cases", ["Dengue is caused by cold weather", "Antibiotics stopped the spread", "The disease spreads only by touch"], "Cases rose with stagnant water after the rain and fell when the water was removed."),
      M(2, "Which pair is correctly matched?", "Cholera — contaminated water; malaria — Anopheles mosquito", ["Cholera — mosquito bites; malaria — contaminated food and water", "Cholera — air; malaria — touch", "Cholera — touch; malaria — air"], "Cholera spreads through contaminated water and malaria through the Anopheles mosquito."),
      M(2, "Ritu has diabetes. Her friend avoids sitting next to her in case she catches it. Is the friend right?", "No, because diabetes is non-infectious and does not spread to others", ["Yes, because diabetes spreads by the air", "Yes, because all diseases spread by touch", "No, because Ritu is not ill"], "Diabetes does not spread from person to person."),
      M(2, "Poor sanitation and crowding help infections to spread because", "germs pass easily through dirty water, food and close contact", ["germs cannot survive in clean places", "crowding makes the weather hot", "sanitation kills the body's defences"], "Dirty surroundings and close contact give germs more ways to reach people."),
      M(2, "Which of these protects a person before infection takes place?", "A vaccine", ["A course of antibiotics", "A painkiller", "Bed rest"], "A vaccine gives protection in advance. Antibiotics are used to treat a bacterial infection."),
      M(2, "Aman sleeps four hours a night, does not play and feels worried. Which change would help his mental well-being most?", "Getting enough sleep, playing and talking to someone he trusts", ["Studying all night", "Staying alone", "Drinking tea to stay awake"], "Sleep, play and talking help mental health. Isolation and lack of sleep make worry worse."),
      M(2, "Keeping food covered helps to prevent disease because it", "keeps flies and dust, which carry germs, away from it", ["adds vitamins to the food", "makes the food heavier", "kills all germs in it"], "Covered food is protected from germs that flies and dust may bring."),
      M(2, "Which of these diseases does not pass from person to person by germs?", "Most cancers", ["Tuberculosis", "Influenza", "Typhoid"], "Most cancers do not spread by germs from person to person. The others are infectious."),
      M(2, "A mosquito is called a vector of malaria because it", "carries the germ from one person to another", ["makes the germ in its body", "is cured by a vaccine", "gets malaria and dies at once"], "A vector is an organism that carries the disease-causing germ from one host to another."),
      M(2, "Before a safe water supply reached a village, there were 120 cholera cases a year. Afterwards there were 30. By what fraction did the cases fall?", "Three quarters", ["One quarter", "One half", "One third"], "Fall = 120 − 30 = 90. 90 out of 120 is three quarters."),
      AR(2, "Vaccines are given to healthy children.", "A vaccine protects the body before the germ attacks.", 0, "Both are true. Protection is needed before infection, which is why a healthy child is vaccinated."),
      AR(3, "Antibiotics should be taken only when a doctor prescribes them.", "Antibiotics kill all viruses.", 2, "A is true. R is false, since antibiotics act on bacteria and not viruses, so wrong use is useless and harmful."),
      M(3, "Which statement about vaccines and antibiotics is correct?", "A vaccine helps to prevent a disease, while an antibiotic treats a bacterial infection", ["Both are used only to treat viral diseases", "An antibiotic always prevents viral diseases, while a vaccine treats bacterial ones only", "Both cure any disease within a day"], "Vaccines give protection beforehand; antibiotics are medicines for bacterial infections."),
      M(3, "Many people in a colony develop cholera, and a well is found to be contaminated. Which single step best stops the spread at once?", "Use boiled or other safe water until the well is made safe", ["Give everyone strong antibiotics without any doctor's advice", "Wait for the rains to wash the well", "Ask people to avoid going out only"], "Cholera spreads by contaminated water, so safe water cuts off the route. Antibiotics are used on a doctor's advice only."),
      M(3, "A child has eaten well and has no disease, but is always afraid to speak with others. A doctor says the child is not fully healthy. This is because", "health also includes mental and social well-being", ["only the stomach affects health", "being afraid is an infectious disease", "health means no sickness only"], "Health is physical, mental and social well-being together."),
    ],
    written: [
      W(1, "What is meant by a balanced diet?", "A diet that contains all the nutrients (carbohydrates, proteins, fats, vitamins, minerals, fibre and water) in the right amounts.", "short"),
      W(1, "Name the insect vector of malaria.", "The female Anopheles mosquito.", "short"),
      W(2, "Name two diseases spread through the air and two spread through water or food.", "Through air: cold, tuberculosis. Through water or food: cholera, typhoid.", "short"),
      W(2, "Why should antibiotics be taken only on a doctor's advice?", "Antibiotics work only against bacteria, not viruses, so they are useless in a cold or influenza. Using them wrongly can harm the person, so the doctor decides the medicine.", "short"),
      W(2, "State two things a person can do to look after mental well-being.", "Talking to family, friends or a counsellor; sleeping enough; playing; doing yoga or hobbies (any two).", "short"),
      W(3, "Explain why smallpox is called an example of the success of vaccination. Who developed its vaccine?", "Smallpox was removed completely from the world by vaccination programmes, so it has been eradicated. The vaccine was developed by Edward Jenner. Polio is another example, where vaccination has nearly eliminated the disease.", "short"),
      W(3, "State three precautions to prevent the spread of infectious diseases at home.", "Wash hands, drink boiled or safe water, keep food covered, remove stagnant water, and cover the mouth while coughing (any three).", "short"),
      W(4, "Case study: During the monsoon, many families in a town get fever. Stagnant water collects in broken pots and open drains. The doctor says it is malaria and asks the town to take action.\n(i) Name the vector.\n(ii) Why does stagnant water increase the cases?\n(iii) Give two steps to reduce the problem.", "(i) The Anopheles mosquito.\n(ii) Mosquitoes breed in standing water, so more water means more mosquitoes to carry the germ.\n(iii) Remove or cover stagnant water; keep drains and tanks covered; use nets; keep surroundings clean (any two).", "case"),
      W(4, "Differentiate between infectious and non-infectious diseases on three points, and give an example of each.", "Infectious: caused by germs; spread from person to person by air, water, food, vectors or contact; can be prevented by hygiene and vaccines. Non-infectious: not caused by germs spreading between people; do not spread from one person to another; need other care such as proper diet. Example: infectious — cholera; non-infectious — diabetes.", "long"),
      W(5, "Explain how a vaccine protects us, and why vaccination is important for the whole community. Use smallpox and polio as examples.", "A vaccine contains a harmless form of the germ, so the body's defence system learns to recognise it. It then responds quickly if the real germ enters later, and the person does not suffer the full disease. When most people in a community are vaccinated, the germ finds few people to spread to, so even the unprotected are safer. Vaccination wiped out smallpox, and has nearly eliminated polio.", "long"),
    ],
  },
    "electricity-magnetic-and-heating-effects": {
    mcq: [
      M(1, "A compass needle placed near a wire deflects while a current flows. When the current is switched off, the needle", "returns to its original position", ["stays deflected even without any current", "spins round and round", "turns to the opposite side"], "The magnetic field exists only while the current flows, so the needle goes back when the current stops."),
      M(1, "Which of these devices works with an electromagnet?", "An electric bell", ["An electric iron", "A toaster", "A geyser"], "An electric bell uses an electromagnet. The iron, toaster and geyser use the heating effect."),
      M(1, "Which of these appliances has a heating element?", "A geyser", ["An electric bell", "A magnetic crane", "A compass"], "A geyser heats water using a coil of high-resistance wire."),
      M(1, "The unit in which the heat produced by a current is measured is the", "joule", ["watt", "ampere", "ohm"], "In H = I²Rt, the heat H is in joules. The ampere, ohm and watt measure current, resistance and power."),
      M(1, "The unit of electrical resistance is the", "ohm", ["ampere", "volt", "joule"], "Resistance is measured in ohms (Ω)."),
      M(1, "A fuse wire melts and breaks the circuit when", "the current becomes too high", ["the switch is turned on", "the bulb is switched off", "the current becomes very small and steady"], "A fuse has a thin wire of low melting point that melts when too much current flows."),
      M(1, "If the number of turns of wire in an electromagnet is increased, the electromagnet becomes", "stronger", ["weaker", "unable to attract anything", "a permanent magnet"], "More turns, more current or a soft iron core all increase the strength."),
      M(1, "Which statement about an electromagnet is correct?", "It is a magnet only while current flows through its coil", ["It stays a magnet for ever", "It works without a coil", "It is made of nichrome"], "When the current stops the electromagnet loses its magnetism."),
      M(2, "A heater of resistance 10 Ω carries 5 A for 2 s. The heat produced is", "500 J", ["100 J", "50 J", "250 J"], "H = I²Rt = 5² × 10 × 2 = 25 × 20 = 500 J."),
      M(2, "A current of 3 A flows through a 40 Ω coil for 10 s. The heat produced is", "3600 J", ["1200 J", "360 J", "400 J"], "H = I²Rt = 3² × 40 × 10 = 9 × 400 = 3600 J."),
      M(2, "A toaster works on 220 V and draws a current of 5 A. Its power is", "1100 W", ["44 W", "225 W", "2200 W"], "P = V × I = 220 × 5 = 1100 W."),
      M(2, "A heating coil produces 600 J in 1 minute. With the same current, the same coil produces in 3 minutes", "1800 J", ["200 J", "600 J", "5400 J"], "H = I²Rt is proportional to the time when I and R are the same, so 3 minutes give 3 × 600 = 1800 J."),
      M(2, "The current through a heating coil is halved while the resistance and the time stay the same. The heat produced becomes", "one quarter", ["one half", "double", "sixteen times"], "H is proportional to I². Half the current gives (1/2)² = 1/4 of the heat."),
      M(2, "Why is nichrome and not copper used for the coil of a heater?", "Nichrome has high resistance and a high melting point, so it gets hot without melting", ["Nichrome is cheaper than any wire", "Nichrome conducts better than copper", "Copper cannot carry a current"], "A heating element must give a lot of heat and stay solid at high temperature, as nichrome does."),
      M(2, "A 5 A fuse is in a circuit, and a fault makes the current 8 A. What happens?", "The fuse wire melts and the circuit breaks", ["The fuse makes the current larger", "The fuse wire becomes a magnet", "Nothing happens, as 8 A is only a little more"], "A current above the fuse rating melts the thin wire, which breaks the circuit and protects the appliances."),
      M(2, "Which statement about a fuse and an MCB is correct?", "An MCB can be reset after it trips, but a blown fuse wire must be replaced", ["A fuse can be reset but an MCB must be replaced", "Both can be reset", "Neither protects against too much current"], "Both cut the circuit at high current. The MCB is a switch that can be turned on again."),
      M(2, "Which change would make an electromagnet stronger?", "Increasing the current and adding more turns of wire", ["Removing the soft iron core", "Reducing the number of turns", "Reducing the current"], "Strength rises with more current, more turns and a soft iron core."),
      M(2, "In an electric bell, what happens to the armature when the circuit is broken?", "The electromagnet loses its magnetism and the armature springs back", ["The armature is pulled harder towards the magnet", "The armature melts", "The gong turns into a magnet"], "The break stops the current, so the armature returns, closing the circuit again. This repeats quickly."),
      M(2, "In Oersted's activity, the current in the wire is increased and the compass needle is watched. The deflection", "becomes larger because the magnetic field is stronger", ["becomes smaller", "does not change at all", "reverses its direction"], "A stronger current gives a stronger magnetic field and so a bigger deflection."),
      M(3, "A geyser's coil glows red hot, but the copper wires joining it to the plug stay cool, though the same current flows through both. This is because", "the coil has much higher resistance, so it produces more heat (H = I²Rt)", ["the coil carries more current", "copper wire is made of nichrome", "the coil is switched on longer"], "The current and time are the same, so the heat depends on resistance. The coil's resistance is far greater."),
      M(3, "For the same resistance and time, the heat produced is 20 J at 1 A, 80 J at 2 A and 180 J at 3 A. What pattern do these readings show?", "The heat is proportional to the square of the current", ["The heat is proportional to the current", "The heat does not depend on the current", "The heat falls as the current rises"], "Doubling the current gives 4 times the heat and tripling it gives 9 times, which matches I²."),
      M(3, "A heater coil carries 4 A and has a resistance of 30 Ω. The heat it produces in 1 minute is", "28 800 J", ["480 J", "7200 J", "18 000 J"], "H = I²Rt = 4² × 30 × 60 = 16 × 30 × 60 = 28 800 J. Remember to change 1 minute to 60 s."),
      M(3, "A coil produces 7200 J in 2 minutes when a current of 5 A flows. Its resistance is", "2.4 Ω", ["1.2 Ω", "12 Ω", "0.48 Ω"], "H = I²Rt, so 7200 = 25 × R × 120 = 3000 R. R = 7200 ÷ 3000 = 2.4 Ω."),
      M(3, "In H = I²Rt, which quantity, when doubled with the other two kept the same, makes the heat four times as large?", "The current", ["The resistance", "The time", "None of the three"], "H depends on I², so doubling the current gives 4 times the heat. Doubling R or t gives only twice the heat."),
      AR(3, "Soft iron is used as the core of an electromagnet.", "Soft iron helps the coil to act as a strong magnet while the current flows.", 0, "Both are true. A soft iron core raises the strength of the electromagnet, which is why it is used."),
      AR(3, "A fuse wire is made of a material with a high melting point.", "A fuse must melt and break the circuit when too much current flows.", 3, "A is false, since a fuse wire has a low melting point. R is true and describes what a fuse must do."),
    ],
    written: [
      W(1, "Write the formula for electrical power and name the unit of each quantity in it.", "P = V × I, where P is power in watts, V is potential difference in volts and I is current in amperes.", "short"),
      W(1, "What is an MCB?", "A miniature circuit breaker, a safety switch that cuts off the circuit automatically when the current is too high, and can be reset.", "short"),
      W(2, "Give two uses of electromagnets other than lifting scrap iron.", "Electric bell, electric motor, relay (any two).", "short"),
      W(2, "What happens to the fuse wire when the current becomes too high? Why is this useful?", "The thin wire melts, which breaks the circuit. This stops the heavy current, so it protects the wires and appliances from overheating and fire.", "short"),
      W(2, "Calculate the power of an electric iron that works on 220 V and draws 4 A.", "P = V × I = 220 × 4 = 880 W.", "short"),
      W(2, "A coil of resistance 15 Ω carries 2 A for 20 s. Find the heat produced.", "H = I²Rt = 2² × 15 × 20 = 4 × 300 = 1200 J.", "short"),
      W(3, "The coil of an electric heater gets hot, but the connecting wire does not. Explain why.", "The same current flows through both for the same time. Heat produced H = I²Rt depends on the resistance. The coil is made of nichrome, which has high resistance, so it produces much heat. The copper connecting wire has low resistance, so it produces very little heat.", "short"),
      W(3, "What did Oersted observe when he reversed the current in the wire and when he increased it? What do these observations show?", "When the current was reversed, the compass needle deflected in the opposite direction. When the current was increased, the deflection became larger. This shows that a current produces a magnetic field, whose direction depends on the direction of the current and whose strength increases with the current.", "short"),
      W(4, "Case study: An electric geyser in a house has a 15 A MCB. One evening the geyser, an iron and a heater are switched on together. The MCB trips and all the lights go off. After the heater is switched off, the MCB is reset and everything works.\n(i) Why did the MCB trip?\n(ii) Why can it be used again, unlike a fuse wire?\n(iii) Give one reason why the heating coils are made of nichrome.", "(i) The total current became more than 15 A, so the MCB cut off the circuit.\n(ii) An MCB is a switch that can be reset after it trips, whereas the wire of a fuse melts and has to be replaced.\n(iii) Nichrome has high resistance, so it gives plenty of heat, and a high melting point, so it does not melt.", "case"),
      W(5, "A heating element of resistance 40 Ω carries a current of 5 A for 10 minutes. (a) Find the heat produced in joules. (b) Find the heat produced per second. (c) By how many times would the heat increase in the same time if the current were doubled?", "(a) t = 10 × 60 = 600 s. H = I²Rt = 5² × 40 × 600 = 25 × 40 × 600 = 600 000 J = 6 × 10⁵ J.\n(b) Heat per second = 600 000 ÷ 600 = 1000 J (this equals 1000 W of power).\n(c) H is proportional to I², so doubling the current makes the heat 4 times as much.", "long"),
    ],
  },
    "exploring-forces": {
    mcq: [
      M(1, "Which of these is a unit of force?", "Newton", ["Kilogram", "Metre", "Litre"], "Force is measured in newtons (N). The kilogram is the unit of mass.", "what-is-force"),
      M(1, "A force has both", "magnitude and direction", ["size only, but no direction", "mass and volume", "shape and colour"], "To describe a force fully we must say how big it is and in which direction it acts.", "what-is-force"),
      M(1, "A magnet picks up a pin without touching it. This pull is an example of a", "non-contact force", ["contact force", "muscular force", "frictional contact force"], "The magnet acts from a distance without touching the pin, so it is a non-contact force.", "what-is-force"),
      M(2, "A goalkeeper catches a fast football and holds it still. What did the force of her hands change?", "The speed of the ball", ["Only the colour of the ball", "The mass of the ball", "Nothing at all"], "A force can change the speed of an object. Here the speed fell to zero.", "what-is-force"),
      M(2, "Which pair of forces acts only when the objects touch?", "Muscular force and friction", ["Gravity and magnetic force", "Magnetic and electrostatic force", "Gravity and electrostatic force"], "Muscular force and friction are contact forces. The others can act at a distance.", "what-is-force"),
      M(2, "A 10 N push on a trolley towards the east and a 10 N push towards the west have the same", "magnitude but different directions", ["direction but different magnitudes", "magnitude and the same direction", "direction and the same effect"], "Both are 10 N, but their directions are opposite, so their effects are different.", "what-is-force"),
      M(1, "When the forces acting on an object are balanced, the net force on it is", "zero", ["equal to the weight", "equal to the biggest force", "twice the biggest force"], "Balanced forces cancel each other, so the net force is zero and the motion does not change.", "net-force"),
      M(2, "A bag hangs at rest from a spring balance. Its weight is 20 N downwards and the spring pulls up with 20 N. What is the net force?", "0 N, so the bag stays at rest", ["40 N downwards", "20 N upwards", "20 N downwards"], "The two forces are equal and opposite, so they balance.", "net-force"),
      M(2, "Forces of 60 N and 45 N act on a cart in opposite directions. The net force is", "15 N in the direction of the 60 N force", ["105 N", "15 N in the direction of the 45 N force", "0 N"], "Opposite forces subtract: 60 − 45 = 15 N, in the direction of the larger force.", "net-force"),
      M(2, "Two forces of 12 N and 18 N act on a box in the same direction. The net force is", "30 N", ["6 N", "216 N", "15 N"], "Forces in the same direction add: 12 + 18 = 30 N.", "net-force"),
      M(2, "Two teams each pull a rope with 300 N in opposite directions. What happens to the rope?", "It does not start to move, as the net force is zero", ["It moves towards the left team", "It moves with a force of 600 N", "It moves to the right team"], "Equal and opposite forces balance, so the state of motion of the rope does not change.", "net-force"),
      M(3, "A box is acted on by 50 N and 20 N to the east and 90 N to the west. The net force is", "20 N to the west", ["20 N to the east", "160 N to the west", "70 N to the west"], "East: 50 + 20 = 70 N. West: 90 N. Net = 90 − 70 = 20 N towards the west.", "net-force"),
      AR(3, "A car moving at a steady speed on a straight road can have balanced forces acting on it.", "Balanced forces make the net force zero, so the motion does not change.", 0, "Both are true. With balanced forces the car continues to move steadily, which explains A.", "net-force"),
      M(1, "Friction acts", "against the motion between surfaces in contact", ["in the same direction as the motion between surfaces", "only in water", "only on smooth surfaces"], "Friction opposes the relative motion of surfaces in contact.", "friction"),
      M(1, "On which surface is it hardest to slide a box?", "A rough cement floor", ["A polished marble floor", "An oily metal sheet", "A smooth wet tile"], "Rough surfaces have more friction.", "friction"),
      M(2, "If a box is pressed harder on the floor, the friction between them", "increases", ["decreases", "becomes zero", "stays the same"], "Friction is larger when the pressing force is greater.", "friction"),
      M(2, "Powder is sprinkled on a carrom board before the game. This is done to", "reduce friction so that the coins slide easily", ["increase friction", "make the coins heavier", "stop the coins from moving"], "A fine powder acts like a lubricant and lowers friction between the striker and the board.", "friction"),
      M(2, "Which is a useful effect of friction?", "Brakes stopping a bicycle", ["Wearing out of tyres", "Heating of the machine parts", "Noise from a rusty hinge"], "Brakes work because of friction. Wear, heating and noise are its drawbacks.", "friction"),
      M(3, "To move a heavy almirah, a force of 400 N is needed to start it, 300 N to keep it sliding, and only 40 N when it is placed on rollers. Which is correct?", "400 N is static friction, 300 N is sliding friction and 40 N is rolling friction", ["400 N is rolling friction and 40 N is static friction", "300 N is static friction and 400 N is sliding friction", "All the values show the same kind of friction"], "Static friction is the largest and rolling friction is the least.", "friction"),
      M(1, "The gravitational force pulls objects", "towards the centre of the Earth", ["away from the Earth", "sideways", "only towards the sea"], "Gravity pulls every object towards the Earth's centre, which is why things fall down.", "field-forces"),
      M(1, "When the north pole of one magnet is brought near the south pole of another magnet, they", "attract each other", ["repel each other strongly", "do not interact", "become weaker"], "Unlike poles attract.", "field-forces"),
      M(2, "A watermelon has a mass of 3.5 kg. Its weight on Earth (g = 10 N/kg) is", "35 N", ["3.5 N", "0.35 N", "13.5 N"], "Weight = mass × g = 3.5 × 10 = 35 N.", "field-forces"),
      M(2, "An astronaut of mass 60 kg goes to the Moon. Her mass there is", "60 kg", ["more than 60 kg", "less than 60 kg", "zero"], "Mass is the amount of matter, which does not change. Only the weight is less on the Moon.", "field-forces"),
      M(2, "Two balloons are rubbed on dry hair, so both get the same kind of charge, and are hung close together. They", "move away from each other", ["move closer towards each other", "stay as before", "stick together"], "Like charges repel one another.", "field-forces"),
      M(3, "A body weighs 150 N on Earth (g = 10 N/kg). Its mass is", "15 kg", ["150 kg", "1500 kg", "1.5 kg"], "Mass = weight ÷ g = 150 ÷ 10 = 15 kg.", "field-forces"),
    ],
    written: [
      W(1, "What is a non-contact force? Give one example.", "A force that acts on an object without touching it, for example gravitational, magnetic or electrostatic force.", "short", "what-is-force"),
      W(1, "Find the weight of a 7 kg object on Earth. Take g = 10 N/kg.", "Weight = mass × g = 7 × 10 = 70 N.", "short", "field-forces"),
      W(2, "Forces of 45 N and 15 N push a trolley in the same direction, and a friction force of 20 N acts against them. Find the net force.", "Forces in the same direction add: 45 + 15 = 60 N. The friction acts opposite, so net force = 60 − 20 = 40 N in the direction of the push.", "short", "net-force"),
      W(2, "Give two examples in which friction is useful.", "Walking without slipping; the brakes of a vehicle; holding a pencil; tying a knot (any two).", "short", "friction"),
      W(2, "State the difference between static friction and sliding friction.", "Static friction acts between surfaces at rest and must be overcome to start the motion, and it is the largest. Sliding friction acts when one surface slides over another, and is less than static friction.", "short", "friction"),
      W(2, "Two balloons are rubbed on dry hair and brought close to each other. What will you observe? Name the force.", "The balloons move apart, as they have the same kind of charge. The force is the electrostatic force, in which like charges repel.", "short", "field-forces"),
      W(3, "A student pushes a box with a force of 10 N, but it does not move. Explain this using friction and balanced forces.", "The friction between the box and the floor acts against the push. Its size is also 10 N, so the two forces are balanced and the net force is zero. Hence the motion of the box does not change.", "short", "net-force"),
      W(3, "Write three differences between mass and weight.", "Mass is the quantity of matter, whereas weight is the gravitational force on the body. Mass is in kg and weight in N. Mass is the same everywhere, but weight changes (it is less on the Moon). Weight = mass × g.", "short", "field-forces"),
      W(4, "Case study: A family is shifting a heavy steel almirah. At first they push with 400 N and it does not move until the force reaches 400 N. Once it slides, a force of 300 N keeps it moving. Then they place it on round wooden rollers, and 40 N is enough.\n(i) Name the three kinds of friction in the order they were met.\n(ii) Which is the smallest, and how do you know?\n(iii) Why do heavy machines use ball bearings?", "(i) Static friction, then sliding friction, then rolling friction.\n(ii) Rolling friction, because only 40 N was needed on the rollers.\n(iii) Ball bearings replace sliding with rolling, which lowers the friction and so reduces wear and heating.", "case", "friction"),
      W(5, "In a tug of war, team A has 5 members pulling 150 N each and team B has 4 members pulling 180 N each, in opposite directions. (a) Find the total pull of each team. (b) Find the net force and say which team moves the rope. (c) One more member, pulling 150 N, joins team B. What happens now?", "(a) Team A: 5 × 150 = 750 N. Team B: 4 × 180 = 720 N.\n(b) Net force = 750 − 720 = 30 N towards team A, so the rope moves towards team A.\n(c) Team B now pulls 720 + 150 = 870 N. Net force = 870 − 750 = 120 N towards team B, so the rope moves towards team B.", "long", "net-force"),
    ],
  },
    "pressure-winds-storms-cyclones": {
    mcq: [
      M(1, "Pressure is defined as the force acting on a surface", "per unit area, at right angles to the surface", ["multiplied by the area", "in any direction on the object", "per unit mass"], "Pressure = force ÷ area, where the force acts perpendicular to the surface."),
      M(1, "Gases exert pressure on", "the walls of the container that holds them", ["nothing at all, as gases have no weight or mass", "the floor only", "liquids only"], "The moving particles of a gas push on the walls of their container, so a gas exerts pressure."),
      M(1, "A liquid exerts pressure", "in all directions", ["only downwards", "only on the bottom", "only upwards"], "Pressure in a liquid acts in all directions on the walls and the objects in it."),
      M(1, "A diver goes deeper and deeper into a lake. The pressure of the water on her", "increases", ["decreases", "stays the same", "becomes zero"], "Liquid pressure increases with depth."),
      M(1, "The pressure exerted by the weight of the air above us is called", "atmospheric pressure", ["hydrostatic pressure", "wind pressure", "cyclone pressure"], "Air has weight, so the atmosphere presses on everything on Earth."),
      M(1, "Which air rises and creates a region of low pressure?", "Warm air", ["Cold air", "Air that is not moving", "Air with no particles"], "Warm air is lighter, so it rises and leaves low pressure below."),
      M(1, "In India, warnings about cyclones are issued by the", "India Meteorological Department (IMD)", ["Survey of India", "Election Commission", "Indian Railways"], "The IMD tracks storms by satellite and gives warnings."),
      M(2, "A force of 500 N acts on an area of 2 m². The pressure is", "250 Pa", ["1000 Pa", "502 Pa", "2.5 Pa"], "P = F ÷ A = 500 ÷ 2 = 250 Pa."),
      M(2, "A pressure of 800 Pa acts on a surface of area 0.5 m². The force on it is", "400 N", ["1600 N", "800.5 N", "0.000625 N"], "F = P × A = 800 × 0.5 = 400 N."),
      M(2, "A force of 1500 N produces a pressure of 3000 Pa. The area on which it acts is", "0.5 m²", ["2 m²", "4 500 000 m²", "1500 m²"], "A = F ÷ P = 1500 ÷ 3000 = 0.5 m²."),
      M(2, "A brick weighing 30 N has faces of 0.02 m² and 0.005 m². The pressure on the ground is greater when it rests on the", "0.005 m² face, and the pressure is 6000 Pa", ["0.02 m² face, and the pressure is only 1500 Pa", "0.005 m² face, and the pressure is 150 Pa", "0.02 m² face, and the pressure is 6000 Pa"], "The same force on a smaller area gives more pressure: 30 ÷ 0.005 = 6000 Pa. On the larger face it is 30 ÷ 0.02 = 1500 Pa."),
      M(2, "A force on a surface is doubled while the area stays the same. The pressure becomes", "twice as much", ["half", "four times as much", "unchanged"], "P = F ÷ A, so doubling F doubles P."),
      M(2, "The same force acts on an area that is made half as large. The pressure becomes", "double", ["half", "the same", "one quarter"], "P = F ÷ A, so halving the area doubles the pressure."),
      M(2, "Tractors working in soft fields have broad tyres because broad tyres", "spread the weight over a larger area and so exert less pressure", ["increase the pressure on the soil", "make the tractor lighter", "reduce the force of gravity"], "A larger area lowers the pressure, so the tractor does not sink in."),
      M(2, "A plastic bottle has three holes at different heights and is filled with water. Water shoots farthest from the lowest hole. This shows that", "liquid pressure increases with depth", ["liquid pressure decreases with depth", "liquid pressure is the same everywhere", "water flows only downwards"], "The lowest hole is the deepest, where the pressure is the greatest, so the water is pushed out the farthest."),
      M(2, "A rubber suction cup sticks to a smooth wall because", "the atmospheric pressure outside is greater than the pressure under the cup", ["glue is present on the wall", "gravity pulls it to the wall", "the wall attracts rubber like a magnet"], "Pressing the cup removes the air beneath it, so the outside air pushes it on to the wall."),
      M(2, "We do not feel the atmospheric pressure even though it is large, because", "the pressure inside our bodies balances it", ["the air has no weight", "the pressure is zero near the ground", "we are used to it, but it does not act on us"], "The pressure inside the body pushes outwards and balances the atmospheric pressure from outside."),
      M(2, "A dropper draws liquid when its rubber bulb is released after squeezing. This is because", "the higher atmospheric pressure on the liquid pushes it into the lower-pressure space in the dropper", ["the liquid is lighter than air", "the bulb pulls the liquid by magnetic force", "gravity pulls the liquid upwards"], "Releasing the bulb lowers the pressure inside, and the atmosphere pushes the liquid in."),
      M(2, "A cyclone warning is given for a coastal village. The best action for the villagers is to", "move to a safe shelter and follow official warnings", ["go to the beach to watch the waves", "shelter under a tall tree", "stay in a weak hut near the sea"], "Warnings, shelters and following official instructions save lives during cyclones."),
      M(2, "Which statement about a cyclone is correct?", "Strong winds spiral around a low-pressure centre", ["It forms over cold, high land", "It has no rain", "It has a high-pressure eye"], "A cyclone forms over warm tropical oceans around a low-pressure centre called the eye."),
      M(3, "During the day, a sea breeze blows from the sea to the land. This happens because", "the warm air over the land rises, giving low pressure, and cooler air from the sea moves in", ["the cooler air over the land rises and the sea air is pulled in", "air over the sea has a lower pressure than air over the land", "winds always blow from the land to the sea"], "Wind blows from high to low pressure. Warm air rises over the land, creating the low-pressure region."),
      M(3, "A student of weight 400 N stands on both feet, whose total area of contact is 0.04 m². When she lifts one foot, the pressure on the ground becomes", "twice as much, that is 20 000 Pa", ["half as much, that is 5000 Pa", "the same, that is 10 000 Pa", "4 times as much, that is 40 000 Pa"], "Before: 400 ÷ 0.04 = 10 000 Pa. On one foot the area is 0.02 m², so P = 400 ÷ 0.02 = 20 000 Pa."),
      AR(3, "A sharp nail goes into a wooden board more easily than a blunt one.", "The pointed tip has a small area, so the same force gives a large pressure.", 0, "Both are true. The smaller area at the tip means greater pressure, which explains why the sharp nail enters the wood."),
      AR(3, "Atmospheric pressure decreases as we climb a mountain.", "There is less air above us at greater heights.", 0, "Both are true. The weight of the air above becomes less with height, so the pressure falls."),
      AR(3, "Wind blows from a region of high pressure to a region of low pressure.", "Warm air rises and creates a low-pressure region, into which cooler air moves.", 0, "Both are true. The rising warm air leaves low pressure, and the cooler air flowing in is the wind."),
    ],
    written: [
      W(1, "State the formula for pressure and the unit in which it is measured.", "Pressure = force ÷ area (P = F/A). The unit is the pascal (Pa), where 1 Pa = 1 N/m².", "short"),
      W(1, "Name the Indian organisation that tracks cyclones with satellites and issues warnings.", "The India Meteorological Department (IMD).", "short"),
      W(2, "The base of a water tank has an area of 4 m² and the tank pushes down with a force of 10 000 N. Calculate the pressure on the ground.", "P = F ÷ A = 10 000 ÷ 4 = 2500 Pa.", "short"),
      W(2, "Why do tractors have broad tyres?", "Broad tyres spread the weight over a larger area. For the same force a larger area means less pressure, so the tractor does not sink into soft soil.", "short"),
      W(2, "Water comes out with more force from the lowest hole of a bottle with holes at different heights. Explain why.", "The pressure of a liquid increases with depth. The lowest hole is the deepest, where the pressure is the greatest, so the water is pushed out the farthest.", "short"),
      W(2, "How does a rubber suction cup stick to a smooth wall?", "When the cup is pressed, the air under it is pushed out, so the pressure inside becomes low. The atmospheric pressure outside is greater and pushes the cup against the wall.", "short"),
      W(3, "Explain how a sea breeze is formed during the day.", "The land becomes warm, and the warm air over it rises, producing a region of low pressure. The air over the sea is cooler and at higher pressure. Wind blows from high pressure to low pressure, so cooler air moves from the sea to the land. This is the sea breeze.", "short"),
      W(3, "A packing box weighing 240 N has a large face of area 0.6 m² and a small face of area 0.2 m². Find the pressure on the floor when it rests on each face, and say which is greater.", "P = F ÷ A.\nLarge face: 240 ÷ 0.6 = 400 Pa.\nSmall face: 240 ÷ 0.2 = 1200 Pa.\nThe pressure is greater on the small face, because the same force acts on a smaller area.", "short"),
      W(4, "Case study: Dark clouds gather on a hot afternoon. Rohan sees lightning and hears thunder. Heavy rain starts. His friends are playing on an open ground with tall trees at the edge.\n(i) Name this type of storm and say how it forms.\n(ii) Where should the children go?\n(iii) Give two other safety rules.", "(i) A thunderstorm. Warm moist air rises quickly, forms clouds and gives heavy rain, lightning and thunder.\n(ii) Into a closed building, away from the open ground and tall trees.\n(iii) Keep away from electric poles; stay indoors; follow official warnings (any two).", "case"),
      W(5, "A woman weighing 500 N wears (a) flat sandals with a total contact area of 0.025 m² and (b) shoes with thin heels that touch the ground over only 0.0005 m². Calculate the pressure on the ground in each case and compare them. What does this show?", "(a) P = F ÷ A = 500 ÷ 0.025 = 20 000 Pa.\n(b) P = 500 ÷ 0.0005 = 1 000 000 Pa.\nThe pressure from the thin heels is 1 000 000 ÷ 20 000 = 50 times that from the sandals. For the same force, a smaller area produces a much greater pressure, so thin heels can dent soft ground.", "long"),
    ],
  },
    "particulate-nature-of-matter": {
    mcq: [
      M(1, "Matter is anything that", "has mass and occupies space", ["has colour, smell and taste", "can be seen with the eye", "is solid"], "Anything with mass that takes up space is matter, whether it is a solid, a liquid or a gas.", "matter-is-made-of-particles"),
      M(1, "The particles of matter are", "always in motion and have spaces between them", ["still and tightly packed with no spaces between them", "moving only when heated", "heavier in solids than in gases"], "According to the particle model, particles are in constant motion and spaces lie between them.", "matter-is-made-of-particles"),
      M(2, "A drop of ink spreads slowly through still water, even when nobody stirs it. This is evidence that", "particles of matter move on their own", ["water is magnetic", "ink is lighter than air", "particles of ink are alive"], "The particles of ink and water mix by their own movement, and no stirring is needed.", "matter-is-made-of-particles"),
      M(2, "A glass is full to the brim with water. Salt is dissolved in it without overflow. This shows that", "there are spaces between water particles", ["salt particles disappear", "salt has no mass", "the glass was not full"], "The salt particles fit into the gaps between the water particles.", "matter-is-made-of-particles"),
      M(2, "When a solid is heated and its particles move faster, the particles themselves", "stay the same size, while the spaces between them grow", ["swell up like balloons", "become lighter", "stop moving"], "Heating makes particles move faster and spread out. The particles themselves do not expand.", "matter-is-made-of-particles"),
      M(3, "Which statement about the particles of matter is correct?", "They attract each other, and the attraction is different in solids, liquids and gases", ["They never attract each other", "The attraction is the same in all three states", "They attract each other only in gases"], "A force of attraction acts between particles. It is strongest in solids and weakest in gases.", "matter-is-made-of-particles"),
      M(1, "Which state of matter has particles that only vibrate about fixed positions?", "Solid", ["Liquid", "Gas", "Vapour"], "The particles of a solid are closely packed and vibrate in place.", "states-of-matter"),
      M(1, "Which state of matter has no fixed shape and no fixed volume?", "Gas", ["Solid", "Liquid", "Ice"], "A gas spreads to fill any container and its volume changes with the container.", "states-of-matter"),
      M(2, "Why can a liquid be poured from one vessel to another?", "Its particles can slide past one another", ["Its particles are locked firmly in fixed places", "Its particles are far apart", "It has no particles"], "Liquid particles are close but free to slide, so liquids flow and take the shape of the vessel.", "states-of-matter"),
      M(2, "A cylinder of cooking gas can hold a large quantity of gas because", "gases can be compressed, as their particles are far apart", ["gas particles are tightly packed", "gas has no particles", "gas particles are heavier than solid ones"], "Large spaces between gas particles allow them to be pushed closer together.", "states-of-matter"),
      M(2, "Which is correct for a liquid?", "It has a fixed volume but no fixed shape", ["It has a fixed shape but no fixed volume", "It has neither fixed shape nor fixed volume", "It has a fixed shape and a fixed volume"], "A liquid takes the shape of its container, but its volume stays the same.", "states-of-matter"),
      M(3, "Arrange the three states in order of increasing force of attraction between particles.", "Gas, liquid, solid", ["Solid, liquid, gas", "Liquid, gas, solid", "Gas, solid, liquid"], "The attraction is weakest in a gas and strongest in a solid.", "states-of-matter"),
      M(1, "The mixing of the smell of food in a room is called", "diffusion", ["evaporation", "sublimation", "freezing"], "Diffusion is the spreading of one substance into another by the movement of particles.", "diffusion"),
      M(2, "In which medium is diffusion the slowest?", "In a solid", ["In a liquid", "In a gas", "In steam"], "Diffusion is fastest in gases, slower in liquids and very slow in solids.", "diffusion"),
      M(2, "Purple potassium permanganate is added to two beakers of water, one hot and one cold. The colour spreads faster in the hot water because", "the particles move faster at a higher temperature", ["hot water has no particles", "the cold particles are heavier", "the crystals become gas"], "A higher temperature increases the speed of particles, so diffusion is quicker.", "diffusion"),
      M(2, "The smell of perfume sprayed in one corner reaches the other corner of the room even on a day without any wind. This is due to", "diffusion of the perfume particles into the air", ["boiling of the perfume", "melting of the perfume", "freezing of the perfume"], "Particles move on their own and mix with the air.", "diffusion"),
      M(3, "A drop of honey and a drop of ink are placed in two glasses of water at the same temperature. Ink spreads faster than honey. Which is the best explanation?", "Ink particles diffuse into water more quickly than the closely packed particles of honey", ["Honey has no particles", "Ink is a gas", "Diffusion does not happen in liquids"], "Diffusion happens in liquids, but at different speeds. Thicker liquids mix more slowly.", "diffusion"),
      M(1, "The change of a solid into a liquid on heating is called", "melting", ["freezing", "condensation", "sublimation"], "Melting is the change from solid to liquid.", "changes-of-state"),
      M(1, "The change of a gas into a liquid on cooling is called", "condensation", ["evaporation", "melting", "solidification"], "Condensation is the change of a gas or vapour into a liquid.", "changes-of-state"),
      M(2, "Which of these changes directly from a solid to a gas on heating?", "Naphthalene", ["Water", "Wax", "Cooking oil"], "Camphor and naphthalene undergo sublimation.", "changes-of-state"),
      M(2, "Water boils at 100 °C at normal pressure. While it is boiling, the temperature of the water", "stays at 100 °C", ["keeps rising slowly", "falls to 90 °C", "becomes 0 °C"], "During a change of state the temperature stays constant. The heat is used to overcome the attraction between particles.", "changes-of-state"),
      M(3, "Water at 20 °C is heated and its temperature is noted every minute: 20, 40, 60, 80, 100, 100, 100, 100 °C. What happens to the water during the readings of 100 °C?", "It boils and changes into steam", ["It freezes", "It stays as it is with no change", "It sublimes"], "The temperature stays constant at the boiling point while the liquid turns to gas.", "changes-of-state"),
      M(1, "Evaporation takes place from", "the surface of a liquid", ["only the bottom of a liquid", "only boiling liquids", "only the inside of a solid"], "Evaporation happens at the surface and at any temperature.", "evaporation-and-cooling"),
      M(2, "Clothes dry faster on a sunny, windy day. The reason is that", "evaporation is quicker when it is warm and there is a breeze", ["clothes absorb sunlight", "wind makes the water boil", "wet clothes sublime"], "Warmth and a breeze speed up evaporation.", "evaporation-and-cooling"),
      M(2, "Water kept in a clay matka stays cool in summer because", "water evaporates from the matka's surface and takes heat from it", ["the clay makes cold", "the water freezes", "the matka is closed"], "Evaporation causes cooling.", "evaporation-and-cooling"),
      AR(2, "Evaporation of sweat cools the body.", "During evaporation the liquid takes heat from the surface that it leaves.", 0, "Both are true. Sweat takes heat from the skin as it evaporates, so we feel cool.", "evaporation-and-cooling"),
    ],
    written: [
      W(1, "Name the change of state in which a solid becomes a liquid.", "Melting.", "short", "changes-of-state"),
      W(1, "A full glass of water can still dissolve a spoonful of salt without overflowing. What two ideas about the particles of matter does this show?", "There are spaces between the particles of water, and the particles of salt fit into those spaces.", "short", "matter-is-made-of-particles"),
      W(2, "A rubber balloon filled with air can be squeezed to a smaller size, but a stone ball of the same size cannot. Explain using the particle model.", "The air particles are far apart, with large spaces between them, so they can be pushed closer together. The stone's particles are packed close together with very small spaces and attract strongly, so they can hardly be pushed closer.", "short", "states-of-matter"),
      W(2, "Why does the smell of cooking spread all through the house?", "The particles of the smell move on their own and mix with the particles of air. This spreading is called diffusion, and it is fast in gases.", "short", "diffusion"),
      W(2, "What is sublimation? Give two examples.", "The change of a solid directly into a gas on heating, without becoming a liquid. Examples: camphor, naphthalene.", "short", "changes-of-state"),
      W(2, "Why does a wet cloth dry faster in the sun than in the shade?", "Evaporation is faster at a higher temperature, because the particles move faster and escape from the surface sooner.", "short", "evaporation-and-cooling"),
      W(3, "Water is heated at normal pressure and its temperature rises to 100 °C. Even if heating continues, the temperature stays at 100 °C while the water boils. Explain.", "At the boiling point the heat supplied is used to overcome the attraction between the particles of water, so that they can separate and become steam. It does not raise the temperature. Hence the temperature stays constant until all the water has boiled.", "short", "changes-of-state"),
      W(3, "Compare evaporation and boiling on three points.", "Evaporation: takes place from the surface only; happens at any temperature; slow and causes cooling. Boiling: takes place throughout the liquid; happens at a fixed temperature, the boiling point; fast and bubbles form.", "short", "evaporation-and-cooling"),
      W(4, "Case study: On a summer afternoon, Arjun places two identical steel tumblers of water, one in the sun and one in a fridge. After an hour he puts a drop of ink in each. The ink spreads quickly in the warmer tumbler and slowly in the cold one. He also sees droplets on the outside of the cold tumbler.\n(i) Name the process by which ink spreads.\n(ii) Why is it faster in the warmer water?\n(iii) How were the droplets on the cold tumbler formed?", "(i) Diffusion.\n(ii) At a higher temperature the particles move faster, so they mix more quickly.\n(iii) Water vapour in the air condensed on the cold surface and turned into liquid droplets.", "case", "diffusion"),
      W(5, "Describe how the particles are arranged and how they move in a solid, a liquid and a gas. For each state say whether the shape and the volume are fixed.", "Solid: particles are closely packed in a fixed pattern and vibrate in place; fixed shape and fixed volume; strongest attraction.\nLiquid: particles are close but can slide past one another; no fixed shape (takes the shape of the container) but fixed volume.\nGas: particles are far apart and move freely in all directions; no fixed shape and no fixed volume; weakest attraction; easily compressed.", "long", "states-of-matter"),
    ],
  },
    });
})();
